import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:fraktal_hmi/data/opcua_gateway_client_io.dart';
import 'package:fraktal_hmi/data/opcua_repository.dart';
import 'package:fraktal_hmi/data/opcua_session_client.dart';
import 'package:fraktal_hmi/domain/types.dart';

void main() {
  test('running native gateway remains live through repeated detail cycles', () async {
    final native = await IoGatewayOpcUaClient.connect(Uri.parse('ws://127.0.0.1:8099/fraktal'),headers: {'origin':'https://press.localhost'});
    final client = _ReadOnly(native);
    final repo = await OpcUaRepository.connectWithClient(client);
    final watch = Stopwatch()..start();
    final links = <Map<String,Object?>>[], snapshots = <Map<String,Object?>>[];
    final linkSub = repo.linkState().listen((link) { links.add({'ms':watch.elapsedMilliseconds,'state':link.name}); });
    final forestSub = repo.forest().listen((forest) { snapshots.add({'ms':watch.elapsedMilliseconds,'roots':forest.length,'detailTags':forest.isEmpty?0:forest.first.publishedTags.keys.where((p)=>p.contains('History')||p.contains('Ring')||p.contains('SequenceSteps')).length}); });
    try {
      repo.setModuleDetailActive('Press',true);
      await Future<void>.delayed(const Duration(seconds:60));
      final result={'controllerWrites':client.writes,'links':links,'forestFrames':snapshots,'snapshotCalls':client.snapshots,'detailBatchSizes':client.batches,'passed':links.isNotEmpty&&links.every((r)=>r['state']=='live')&&snapshots.every((r)=>r['roots']==1)&&client.writes==0&&client.batches.length>=6};
      result['wireSamples']=client.samples;
      File('C:/work/press68_loop_live_verified.json').writeAsStringSync(jsonEncode(result));
      print(jsonEncode({'links':links,'forestFrames':snapshots.length,'snapshotCalls':client.snapshots,'detailBatches':client.batches.length,'controllerWrites':client.writes,'passed':result['passed']}));
      expect(result['passed'],isTrue);
    } finally {
      await linkSub.cancel(); await forestSub.cancel(); repo.dispose();
    }
  },timeout: const Timeout(Duration(seconds:90)));
}

// Only the ConfigRev-triggered mailbox hydration is omitted from this read-only
// probe. Real transport, discovery, tiers, values, metadata, mapper, watchdog,
// detail scheduling and complete-sample refresh are the production paths.
class _ReadOnly implements OpcUaBulkReadClient,OpcUaTieredReadClient {
  final IoGatewayOpcUaClient native;
  int writes=0,snapshots=0;
  final batches=<int>[];
  final samples=<Map<String,Object?>>[];
  _ReadOnly(this.native);
  @override Future<Map<String,Object?>> snapshot() async {
    snapshots++;
    final watch=Stopwatch()..start();
    final doc=await native.snapshot();
    samples.add({'rpcMs':watch.elapsedMicroseconds/1000,'serverSampleAgeMs':doc['sampleAgeMs'],'values':(doc['values'] as Map).length,'freshnessBudget':doc['freshnessBudget']});
    return {...doc,'values':{for(final item in (doc['values'] as Map).entries) if(!'${item.key}'.endsWith('/ConfigRev')) '${item.key}':item.value},'dataValues':{for(final item in (doc['dataValues'] as Map).entries) if(!'${item.key}'.endsWith('/ConfigRev')) '${item.key}':item.value}};
  }
  @override Future<Map<String,Object?>> readValues(List<String> paths) {batches.add(paths.length);return native.readValues(paths);}
  @override Future<void> setSlowPaths(Iterable<String> paths)=>native.setSlowPaths(paths);
  @override Future<void> setExcludedPaths(Iterable<String> paths)=>native.setExcludedPaths(paths);
  @override Future<void> refreshSlowPaths()=>native.refreshSlowPaths();
  @override Future<bool> write(String path,OpcUaWriteType type,Object value) async {writes++;throw StateError('read-only probe forbids PLC writes');}
  @override Future<void> close()=>native.close();
}
